use Illuminate\Database\Eloquent\Builder;

Post::has('comments')->get();                      // kam se kam 1 comment
Post::has('comments', '>=', 3)->get();             // 3 ya zyada
Post::doesntHave('comments')->get();               // koi comment nahi

Post::whereHas('comments', function (Builder $query) {
    $query->where('body', 'like', '%laravel%');
})->get();                                         // laravel wale comments waali posts

Post::whereDoesntHave('comments', fn (Builder $q) => $q->where('approved', false))->get();

$posts = Post::withCount('comments')
    ->orderByDesc('comments_count')
    ->limit(10)
    ->get();

foreach ($posts as $post) {
    echo "{$post->title}: {$post->comments_count} comments";
}

// Kai counts aur condition ke saath:
Post::withCount([
    'comments',
    'comments as approved_comments_count' => fn ($q) => $q->where('approved', true),
])->get();

$user = User::find(1);

Post::whereBelongsTo($user)->get();       // is user ke posts

